struct Meters { unsigned long long m; };

// UDL definition for integer literals
constexpr Meters operator""_m(unsigned long long val) {
    return Meters{ val };
}

// UDL definition for float literals
constexpr Meters operator""_m(long double val) {
    return Meters{ (unsigned long long)(val) };
}

constexpr Meters d1 = 42_m;        // Compile-time integer UDL
constexpr Meters d2 = 10.5_m;      // Compile-time float UDL
// d1.m == 42
// d2.m == 10
